import{_ as a,o as n,c as e,ag as l}from"./chunks/framework.BcBuEkoe.js";const u=JSON.parse(`{"title":"WSL 🍻","description":"I like windows's UI simple I can do jobs faster than mac and adding linux terminal on that is perfect work environment for me.","frontmatter":{"head":[["meta",{"name":"description","content":"I like windows's UI simple I can do jobs faster than mac and adding linux terminal on that is perfect work environment for me."}],["meta",{"name":"keywords","content":"wsl"}]]},"headers":[],"relativePath":"posts/wsl.md","filePath":"posts/wsl.md","lastUpdated":1789372242000}`),o={name:"posts/wsl.md"};function t(p,s,r,c,i,d){return n(),e("div",null,s[0]||(s[0]=[l(`<h1 id="wsl-🍻" tabindex="-1">WSL 🍻 <a class="header-anchor" href="#wsl-🍻" aria-label="Permalink to &quot;WSL 🍻&quot;">​</a></h1><blockquote><p>I LOVE WSL!</p></blockquote><p>I like windows&#39;s UI simple I can do jobs faster than mac and adding linux terminal on that is perfect work environment for me.</p><p>Some benefist of this setup:</p><ul><li>Use new windows terminal (best terminal ever) setting default terminal to wsl</li><li>Run docker under wsl</li><li>Vscode and see the wsl file system</li><li>View Linux gui apps under wsl</li><li>Runnable .exe files from terminal</li></ul><p>There is still some cons, need to much more flexibility of the wsl machine like networking, passthrough devices.</p><h2 id="issues" tabindex="-1">Issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;Issues&quot;">​</a></h2><h3 id="cannot-execute-windows-binaries" tabindex="-1">Cannot execute windows binaries <a class="header-anchor" href="#cannot-execute-windows-binaries" aria-label="Permalink to &quot;Cannot execute windows binaries&quot;">​</a></h3><blockquote><p>Old trick, looks not needed anymore</p></blockquote><p><a href="https://github.com/microsoft/WSL/issues/8843#issuecomment-1459120198" target="_blank" rel="noreferrer">microsoft/WSL#8843 (comment)</a></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#C3E88D;"> sh</span><span style="color:#C3E88D;"> -c</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">echo :WSLInterop:M::MZ::/init:PF &gt; /usr/lib/binfmt.d/WSLInterop.conf</span><span style="color:#89DDFF;">&#39;</span></span></code></pre></div><p>After shutdown and restart WSL, you can execute windows binaries.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">wsl</span><span style="color:#C3E88D;"> --shutdown</span></span></code></pre></div><h3 id="wsl-hard-disk-got-all-space" tabindex="-1">WSL - hard disk got all space <a class="header-anchor" href="#wsl-hard-disk-got-all-space" aria-label="Permalink to &quot;WSL - hard disk got all space&quot;">​</a></h3><p>First install <code>Optimize-VHD</code> and it is come with <code>Microsoft-Hyper-V</code> check powershell and if not exist than install it:</p><blockquote><p>Remember to run powershell as administrator</p></blockquote><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">Enable-WindowsOptionalFeature</span><span style="color:#89DDFF;"> -</span><span style="color:#EEFFFF;">Online </span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">FeatureName Microsoft</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">Hyper</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">V </span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">All</span></span></code></pre></div><p>Or just management tools:</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">Enable-WindowsOptionalFeature</span><span style="color:#89DDFF;"> -</span><span style="color:#EEFFFF;">Online </span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">FeatureName Microsoft</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">Hyper</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">V</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">Management</span><span style="color:#89DDFF;">-</span><span style="color:#EEFFFF;">PowerShell</span></span></code></pre></div><p>Than in your <code>ext4.vhdx</code> file location run (this takes time):</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">Optimize-VHD</span><span style="color:#89DDFF;"> -</span><span style="color:#EEFFFF;">Path </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">C:\\Users\\rytsh\\AppData\\Local\\Packages\\CanonicalGroupLimited.Ubuntu_42thkp1fnegsc\\LocalState\\ext4.vhdx</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> -</span><span style="color:#EEFFFF;">Mode Full</span></span></code></pre></div><blockquote><p>Use windirstat program easily to find big files <a href="https://windirstat.net/" target="_blank" rel="noreferrer">https://windirstat.net/</a></p></blockquote><h3 id="xdg-open" tabindex="-1">xdg-open <a class="header-anchor" href="#xdg-open" aria-label="Permalink to &quot;xdg-open&quot;">​</a></h3><p>Redirect xdg-open to powershell.exe start command, so you can open files from wsl terminal.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#C3E88D;"> tee</span><span style="color:#C3E88D;"> /usr/local/bin/xdg-open</span><span style="color:#89DDFF;"> &lt;&lt;</span><span style="color:#89DDFF;">EOF</span></span>
<span class="line"><span style="color:#C3E88D;">#!/bin/sh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C3E88D;">powershell.exe -c start &quot;&#39;</span><span style="color:#EEFFFF;">\\$</span><span style="color:#C3E88D;">@&#39;&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">EOF</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#C3E88D;"> chmod</span><span style="color:#C3E88D;"> +x</span><span style="color:#C3E88D;"> /usr/local/bin/xdg-open</span></span></code></pre></div><blockquote><p><a href="https://stackoverflow.com/questions/56633006/open-windows-native-exe-program-via-xdg-open-in-wsl" target="_blank" rel="noreferrer">https://stackoverflow.com/questions/56633006/open-windows-native-exe-program-via-xdg-open-in-wsl</a></p></blockquote><p>Set browser so golang use that one directly:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#C3E88D;"> tee</span><span style="color:#C3E88D;"> /usr/local/bin/windows-browser</span><span style="color:#89DDFF;"> &gt;</span><span style="color:#C3E88D;">/dev/null</span><span style="color:#89DDFF;"> &lt;&lt;</span><span style="color:#89DDFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="color:#C3E88D;">#!/bin/sh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C3E88D;">url=&quot;$1&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C3E88D;">case &quot;$url&quot; in</span></span>
<span class="line"><span style="color:#C3E88D;">  file://*)</span></span>
<span class="line"><span style="color:#C3E88D;">    path=&quot;\${url#file://}&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">    distro=&quot;$(wsl.exe -l -q | tr -d &#39;\\r&#39; | head -n1)&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">    winpath=&quot;\\\\\\\\wsl.localhost\\\\\${distro}$(printf &#39;%s&#39; &quot;$path&quot; | sed &#39;s#/#\\\\#g&#39;)&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">    powershell.exe -NoProfile -Command &quot;Start-Process &#39;$winpath&#39;&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">    ;;</span></span>
<span class="line"><span style="color:#C3E88D;">  *)</span></span>
<span class="line"><span style="color:#C3E88D;">    powershell.exe -NoProfile -Command &quot;Start-Process &#39;$url&#39;&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">    ;;</span></span>
<span class="line"><span style="color:#C3E88D;">esac</span></span>
<span class="line"><span style="color:#89DDFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#C3E88D;"> chmod</span><span style="color:#C3E88D;"> +x</span><span style="color:#C3E88D;"> /usr/local/bin/windows-browser</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">cat</span><span style="color:#89DDFF;"> &lt;&lt;</span><span style="color:#89DDFF;">&#39;EOF&#39;</span><span style="color:#89DDFF;"> &gt;&gt;</span><span style="color:#C3E88D;"> ~/.bashrc</span></span>
<span class="line"><span style="color:#C3E88D;">export BROWSER=/usr/local/bin/windows-browser</span></span>
<span class="line"><span style="color:#89DDFF;">EOF</span></span></code></pre></div>`,28)]))}const h=a(o,[["render",t]]);export{u as __pageData,h as default};
